import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Cash collection & office handover","description":"","frontmatter":{},"headers":[],"relativePath":"plus/cash-management.md","filePath":"plus/cash-management.md"}'),r={name:"plus/cash-management.md"};function i(c,e,s,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="cash-collection-office-handover" tabindex="-1">Cash collection &amp; office handover <a class="header-anchor" href="#cash-collection-office-handover" aria-label="Permalink to &quot;Cash collection &amp; office handover&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Source-reviewed against TransferBook+ v0.7.26. Verify the installed release, company, permissions and configuration. Use authorized synthetic data for training. Commercial activation is not asserted.</p></div><h2 id="collect-money-during-a-journey" tabindex="-1">Collect money during a journey <a class="header-anchor" href="#collect-money-during-a-journey" aria-label="Permalink to &quot;Collect money during a journey&quot;">​</a></h2><ol><li>Confirm the authorized chauffeur, reservation and independent leg. Review the server-verified balance before accepting cash.</li><li>Enter only the amount physically received, either a partial payment or the remaining balance. Confirm once and inspect the resulting receipt and updated balance. Do not record cash before receipt or create another entry after an uncertain response.</li><li>The collection receipt records the collecting chauffeur and awaits physical office handover. Passenger settlement and office custody are different events.</li></ol><h2 id="close-the-cash-ledger" tabindex="-1">Close the cash ledger <a class="header-anchor" href="#close-the-cash-ledger" aria-label="Permalink to &quot;Close the cash ledger&quot;">​</a></h2><ol><li>In the approved payment workspace, inspect the cash receipts, original collecting chauffeur and prior handovers.</li><li>Count the physical cash and match the full receipt amount. Confirm handover only after actual transfer to the office. If the physical amount differs, investigate; do not make a false confirmation.</li><li>A different custody holder requires authorized company_admin review and a documented custody-transfer reason. The backend rejects mismatched or duplicate handovers outside the supported rules.</li><li>Verify the handover record and reconcile against receipts, payment and refund history. A dashboard aggregate is not an authoritative cash ledger.</li></ol><p>Use authorized synthetic records for acceptance. Do not equate a payment authorization, invoice, checkout link or outstanding-value indicator with money received. For an unresolved payment or conflicting amount, stop and investigate before retrying.</p><p>See <a href="/plus/payments-and-reconciliation.html">Payments and reconciliation</a> and <a href="/plus/chauffeur-workspace.html">Chauffeur workspace</a>.</p>',8)])])}const p=a(r,[["render",i]]);export{u as __pageData,p as default};
